import { useState, useEffect } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import { toast } from 'sonner'
import { AlertCircle } from 'lucide-react'
import AuthLayout from '../components/auth/AuthLayout'
import Button from '../components/ui/Button'

export default function VerificationPendingPage() {
  const navigate = useNavigate()
  const user = JSON.parse(localStorage.getItem('user') || 'null')
  const email = user?.email || ''

  const [resending, setResending] = useState(false)
  const [error, setError] = useState('')
  const [cooldown, setCooldown] = useState(0)

  useEffect(() => {
    let timer
    if (cooldown > 0) {
      timer = setTimeout(() => setCooldown(cooldown - 1), 1000)
    }
    return () => clearTimeout(timer)
  }, [cooldown])

  useEffect(() => {
    let active = true
    async function checkVerificationStatus() {
      try {
        const response = await fetch('/api/v1/auth/me')
        if (response.ok && active) {
          const freshUser = await response.json()
          if (freshUser.is_verified === true) {
            const localUser = JSON.parse(localStorage.getItem('user') || 'null')
            const merged = { ...localUser, ...freshUser }
            localStorage.setItem('user', JSON.stringify(merged))
            window.dispatchEvent(new Event('userLoggedIn'))
            toast.success('Email verified successfully!')
            navigate('/dashboard', { replace: true })
          }
        }
      } catch (err) {
        // ignore
      }
    }

    if (user && user.is_verified === false) {
      // Check status immediately
      checkVerificationStatus()

      // Also check status when the user switches back/focuses the tab
      const handleFocus = () => {
        checkVerificationStatus()
      }
      window.addEventListener('focus', handleFocus)
      return () => {
        active = false
        window.removeEventListener('focus', handleFocus)
      }
    }

    return () => {
      active = false
    }
  }, [navigate, user])

  async function handleResend() {
    if (!email) {
      toast.error('No email address associated with session.')
      return
    }

    setResending(true)
    setError('')

    try {
      const response = await fetch('/api/auth/resend-verification', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email }),
      })

      const data = await response.json().catch(() => ({}))

      if (!response.ok) {
        throw new Error(data.error || 'Failed to resend verification link.')
      }

      toast.success(data.message || 'Verification link has been resent! Check your inbox.')
      setCooldown(60) // Start 60 second cooldown
    } catch (err) {
      setError(err.message || 'Failed to send email.')
      toast.error(err.message || 'Failed to send email.')
    } finally {
      setResending(false)
    }
  }

  const handleLogout = async () => {
    try {
      await fetch('/api/v1/auth/logout', { method: 'POST', credentials: 'include' })
    } catch {
      // ignore
    }
    if (window.posthog) {
      window.posthog.reset()
    }
    localStorage.removeItem('user')
    window.dispatchEvent(new Event('userLoggedIn'))
    toast.success('Logged out successfully.')
    navigate('/login')
  }

  return (
    <AuthLayout
      eyebrow="Verification"
      title="Verify Your Email"
      subtitle="Your account is pending email validation before accessing fully protected features."
    >
      <div className="mt-6 space-y-6">
        <div className="rounded-lg border border-line glass-box p-4 backdrop-blur-sm">
          <p className="text-sm text-ink-2 mb-2">
            A confirmation link was dispatched to:
          </p>
          <p className="font-mono text-sm font-semibold text-accent break-all select-all">
            {email || 'No active session email'}
          </p>
        </div>
        
        <div className="rounded-lg border border-amber-500/30 bg-amber-500/10 p-4 flex items-start gap-3">
          <AlertCircle className="h-5 w-5 text-amber-600 mt-0.5 shrink-0" />
          <div className="text-sm text-amber-800 dark:text-amber-200">
            <p className="font-semibold mb-1">Didn't receive it?</p>
            <p>Emails can sometimes take a minute. Please double-check your <span className="font-bold">spam or junk folder</span> before requesting a new link.</p>
          </div>
        </div>

        <div className="flex flex-col gap-2">
          <Button
            variant="primary"
            onClick={handleResend}
            disabled={resending || !email || cooldown > 0}
            className="w-full font-semibold"
          >
            {resending ? 'Resending Link...' : cooldown > 0 ? `Resend Verification Link (${cooldown}s)` : 'Resend Verification Link'}
          </Button>

          <Button
            variant="secondary"
            onClick={() => navigate('/dashboard')}
            className="w-full font-semibold"
          >
            Continue to Dashboard
          </Button>
        </div>

        {error && (
          <p className="rounded-lg border border-danger bg-danger-soft px-3 py-2 text-sm text-danger text-center">
            {error}
          </p>
        )}

        <div className="flex flex-col items-center justify-center gap-3 text-sm text-muted">
          <button
            onClick={handleLogout}
            className="font-semibold text-accent hover:underline focus:outline-none"
          >
            Sign out / Login to another account
          </button>
        </div>
      </div>
    </AuthLayout>
  )
}
